// Root SKILL.md cases with the market's parse result: { name, description, version } or null for skill_md_invalid.
// Shared by the unit tests and by a parity run against the server's ParseSkillMD.
const fm = (body, rest = '# x\n') => `---\n${body}---\n${rest}`;
const ok = (name, description, version = '') => ({ name, description, version });
const D = 'description: d\n';

export const frontmatterCases = {
  'plain': [fm(`name: demo\n${D}`), ok('demo', 'd')],
  'CRLF': [fm(`name: demo\n${D}`).replaceAll('\n', '\r\n'), ok('demo', 'd')],
  'lone CR': [fm(`name: demo\r${D}`), null],
  'BOM': [`\ufeff${fm(`name: demo\n${D}`)}`, null],
  'no frontmatter': ['# x\n', null],
  'not closed': ['---\nname: demo\ndescription: d\n', null],
  'NEL in unclosed body': ['---\nname: demo\n\u0085\n', null],
  'closing line with blank': [`---\nname: demo\n${D}--- \n`, null],
  'quoted values': [fm(`name: "demo"\ndescription: 'it''s # not a comment' # c\n`), ok('demo', "it's # not a comment")],
  'escape in double quotes': [fm(`name: demo\ndescription: "a\\"b"\n`), null],
  'unclosed quote': [fm(`name: demo\ndescription: "abc\n`), null],
  'text after quote': [fm(`name: demo\ndescription: "a" b\n`), null],
  'comment stripped': [fm(`name: demo # x\ndescription: a b #c\n`), ok('demo', 'a b')],
  'hash without blank': [fm(`name: demo\ndescription: a#b\n`), ok('demo', 'a#b')],
  'colon space in plain': [fm(`name: demo\ndescription: a: b\n`), null],
  'trailing colon': [fm(`name: demo\ndescription: a:\n`), null],
  'colon without space': [fm(`name: demo\ndescription: a:b\n`), ok('demo', 'a:b')],
  'indicator start': [fm(`name: demo\ndescription: &a x\n`), null],
  'dash start': [fm(`name: demo\ndescription: - x\n`), null],
  'dash word': [fm(`name: demo\ndescription: -x\n`), ok('demo', '-x')],
  'continuation line': [fm(`name: demo\n${D}  more\n`), null],
  'block literal': [fm(`name: demo\ndescription: |\n  line one\n\n  line two\nversion: 1.0.0\n`), ok('demo', 'line one\n\nline two', '1.0.0')],
  'block folded strip': [fm(`name: demo\ndescription: >-\n  a\n    b\n`), ok('demo', 'a b')],
  'block keep': [fm(`name: demo\ndescription: |+\n  a\n`), null],
  'block on name': [fm(`name: |\n  demo\n${D}`), null],
  'empty block': [fm(`name: demo\ndescription: |\n`), null],
  'duplicate name': [fm(`name: demo\nname: demo\n${D}`), null],
  'other keys': [fm(`name: demo\n${D}metadata:\n  a: [1, 2]\n- x\nlicense: "MIT"\ntags: [a, "b, c"] # t\n`), ok('demo', 'd')],
  'list after scalar key': [fm(`name: demo\n${D}- x\n`), null],
  'unclosed flow': [fm(`name: demo\n${D}tags: [a, b\n`), null],
  'text after flow': [fm(`name: demo\n${D}tags: [a] b\n`), null],
  'uppercase key': [fm(`name: demo\n${D}Name: x\n`), null],
  'quoted key': [fm(`name: demo\n${D}"x": y\n`), null],
  'tab after colon': [fm(`name:\tdemo\ndescription:\td\n`), ok('demo', 'd')],
  'tab-indented line': [fm(`name: demo\n${D}\tx: y\n`), null],
  'bad slug': [fm(`name: Demo\n${D}`), null],
  'double dash slug': [fm(`name: a--b\n${D}`), null],
  'slug 64': [fm(`name: ${'a'.repeat(64)}\n${D}`), ok('a'.repeat(64), 'd')],
  'slug 65': [fm(`name: ${'a'.repeat(65)}\n${D}`), null],
  'description missing': [fm('name: demo\n'), null],
  'description 500 chars': [fm(`name: demo\ndescription: ${'\u00e9'.repeat(500)}\n`), ok('demo', '\u00e9'.repeat(500))],
  'description 501 chars': [fm(`name: demo\ndescription: ${'\u{1f600}'.repeat(501)}\n`), null],
  'version prerelease': [fm(`name: demo\n${D}version: 1.2.3-rc.1\n`), ok('demo', 'd', '1.2.3-rc.1')],
  'version with v': [fm(`name: demo\n${D}version: v1.2.3\n`), null],
  'version build metadata': [fm(`name: demo\n${D}version: 1.2.3+b\n`), null],
  'version leading zero': [fm(`name: demo\n${D}version: 01.2.3\n`), null],
  'version empty': [fm(`name: demo\n${D}version:\n`), null],
  'version 65 bytes': [fm(`name: demo\n${D}version: 1.2.3-${'a'.repeat(59)}\n`), null],
  'C1 control in value': [fm(`name: demo\ndescription: a\u0080b\n`), null],
  'U+2028 in value': [fm(`name: demo\ndescription: a\u2028b\n`), null],
};
